//! Parameter tables. The `*_data` modules are generated by `scripts/gen_data.py` from the
//! reference Fortran sources, bit-identical to the compiled parameters.

#[rustfmt::skip] // parameter tables keep their compact layout
pub mod eeq_data;
#[rustfmt::skip] // parameter tables keep their compact layout
pub mod element_data;
#[rustfmt::skip] // parameter tables keep their compact layout
pub mod gfn2_data;
#[rustfmt::skip] // parameter tables keep their compact layout
pub mod sto_data;
#[rustfmt::skip] // parameter tables keep their compact layout
pub mod xtb_data;

/// Pauling electronegativity of element `z` (1-based).
#[inline]
pub fn pauling_en(z: usize) -> f64 {
    element_data::PAULING_EN[z - 1]
}

/// D3 covalent radius (bohr) of element `z` (1-based), used by the xTB coordination numbers.
#[inline]
pub fn covalent_rad_d3(z: usize) -> f64 {
    element_data::COVALENT_RAD_D3[z - 1]
}

/// Atomic radius (bohr) of element `z` (1-based), used in the xTB shell polynomials.
#[inline]
pub fn atomic_rad(z: usize) -> f64 {
    element_data::ATOMIC_RAD[z - 1]
}

/// D3 covalent radius (bohr) converted from Ångström with the CODATA 2022 bohr radius
/// (axtb conventions): 4/3 of the Pyykko-Atsumi radius.
#[inline]
pub fn covalent_rad_d3_codata2022(z: usize) -> f64 {
    4.0 / 3.0 * (element_data::COVALENT_RAD_2009_AA[z - 1] * crate::units::AATOAU)
}

/// Atomic radius (bohr) converted with the CODATA 2022 bohr radius (axtb conventions).
#[inline]
pub fn atomic_rad_codata2022(z: usize) -> f64 {
    element_data::ATOMIC_RAD_AA[z - 1] * crate::units::AATOAU
}

#[cfg(test)]
mod tests {
    use super::element_data;
    use crate::units::reference::MCTC_AATOAU as AATOAU;
    use axtb_base::elements;

    fn bits(v: &[f64]) -> Vec<u64> {
        v.iter().map(|x| x.to_bits()).collect()
    }

    /// axtb-base's element tables equal the core's copies bit for bit, and the bohr radii
    /// derived from the Ångström table as `aatoau * r` (the operation of mctc-lib's declaration)
    /// equal the core's literal products.
    #[test]
    fn base_element_tables_equal_the_core_copies() {
        const DERIVED: [f64; 118] = {
            let mut r = [0.0; 118];
            let mut i = 0;
            while i < 118 {
                r[i] = AATOAU * elements::COVALENT_RAD_2009_AA[i];
                i += 1;
            }
            r
        };
        assert_eq!(bits(&elements::PAULING_EN), bits(&element_data::PAULING_EN));
        assert_eq!(bits(&elements::COVALENT_RAD_2009_AA), bits(&element_data::COVALENT_RAD_2009_AA));
        assert_eq!(bits(&DERIVED), bits(&element_data::COVALENT_RAD_2009));
    }
}
